import{readFile,writeFile,stat}from'node:fs/promises';import{fileURLToPath}from'node:url';import ts from'typescript';
const dir=fileURLToPath(new URL('../../docs/qa/layout-audit-2026-11-16',import.meta.url));const js=ts.transpileModule(await readFile(new URL('./AuditScenarios.ts',import.meta.url),'utf8'),{compilerOptions:{module:ts.ModuleKind.ESNext,target:ts.ScriptTarget.ES2022}}).outputText;const{auditScenarios}=await import('data:text/javascript;base64,'+Buffer.from(js).toString('base64'));
