let html=`<!doctype html><html lang="zh"><meta charset="utf-8"><title>Figma 对照与离线场景验收</title><style>body{font:15px/1.6 system-ui;background:#f4f6fa;color:#243041;margin:24px}main{max-width:1450px;margin:auto}table{width:100%;border-collapse:collapse;margin:20px 0;background:white}td,th{border:1px solid #d4dbe4;padding:12px;vertical-align:top}th{background:#e8eef5}img{max-width:100%;width:220px}td:nth-last-child(-n+2){width:23%}small{color:#516274}nav{position:sticky;top:0;background:white;padding:10px}a{color:#175f99}.note{background:#fff5d7;padding:16px}details{margin:12px 0}</style><main><h1>kong：Figma 原稿 ↔ 当前实现</h1><p>2026-11-16 · 离线真实组件、合成数据、移动触控 Chrome · 所有图可点击放大。旧“修改前/后”对照已由此报告取代。</p><nav>${Object.entries(names).map(([id,n])=>`<a href="#${id}">${n}</a>`).join(' · ')} · <a href="#catalog">新增模拟清单</a></nav><p class="note">“场景加载”只表示完成截图且未出现脚本错误，不等同逐像素验收通过。Figma 没有给出每一种业务状态，状态图左侧仅作为布局基准；不会伪造对应设计稿。职业横屏按用户决定暂缓，牌面保留两套。初代尚未取得独立 Figma 原图，保留现有适配，单列证据缺口。</p><h2>原图来源</h2><ul><li>均衡：Figma 节点 <a href="https://www.figma.com/design/T8R5QTx2OHl8zCqxoW8FkO/Game-Design?node-id=12026-53752">12026:53752</a>，原生导出 440×782，未缩放、未重绘。</li><li>竞技椭圆：用户“最终交付”<a href="reference/oval-full-original.png">完整原图</a>，100% 视口裁切 x=528 y=295 w=440 h=782。</li><li>经典：用户“最终交付”<a href="reference/classic-full-original.png">完整原图</a>，100% 视口裁切 x=735 y=229 w=440 h=782。</li></ul><h2>本轮坐标修改</h2><p>座位布局决定头像锚点，手牌、庄家、下注、状态、牌型和操作区使用相对偏移，再乘现有布局与座位缩放。短屏先上移整个本人组件，子元素跟随；不把设计 px 当作设备屏幕 px，也没有简单替换为 rem。</p><ul><li>均衡本人牌：100% 基准 40×56，牌心距头像中心下方 65，头像与牌面净距 7；庄家偏移（−54，118）。</li><li>竞技椭圆：同类手牌偏移沿用其布局参数，50 头像产生 12 的牌面间距；各布局分别保留头像尺寸。</li><li>经典：本人牌 50×71，庄家偏移（−107，−7）。</li><li>新布局操作按钮和拉杆改为跟随本人头像；拉杆确认保留加注按钮位置。其他玩家庄家标记也以各自头像为原点。</li></ul><p>头像几何与交互检查已记录 ${verify.length} 条；工作台附加交互 ${interactions.length} 条（<a href="workbench-verification.json">详情</a>）：<a href="avatar-verification.json">原始结果</a>。页面装载和截图的证据见 <a href="scenario-results-all.json">场景结果</a>。</p>`;
const rows=[];
for(const[id,name]of Object.entries(names)){
 html+=`<h2 id="${id}">${name}</h2><table><tr><th>验收项 / 修改说明</th><th>Figma 原图（100%）</th><th>当前实现（440×782）</th></tr><tr><td>本人/他人头像、手牌、昵称、筹码、庄家、操作类型、公共牌、底池及操作区。${id==='original'?'保留原布局；Figma 原图缺失，不能判断设计一致性。':'本轮修正头像相对坐标；图片供逐项视觉核对。'}<p>动态头像、示例牌值/金额与设计稿可能不同；底栏高度、背景配色、对手亮牌等细节仍须按图复核，未标为像素一致。</p></td><td>${refs[id]?photo('reference/'+refs[id],name+' Figma 原图'):'未取得对应原图'}</td><td>${photo('scenarios/'+id+'-figma.jpg',name+' 当前实现')}</td></tr></table>`;

 const elements=[['本人手牌尺寸/比例','figma','新布局使用独立牌宽高，复用牌面组件。'],['本人手牌与头像间隔','figma','偏移挂在本人头像；均衡100%净距7，椭圆净距12。'],['本人庄家标记','dealer-self','五种视口检查与手牌/筹码不相交。'],['其他玩家庄家标记','dealer-other','相对各自头像偏移；可轮转庄位。'],['其他玩家牌背尺寸/位置','actions','逐座位核对左右方向，牌背叠头像为原结构。'],['其他玩家亮牌','revealed','亮牌与牌背分别布局，原稿未包含所有座位的亮牌状态。'],['四/五/六张手牌','six','复用定宽牌组叠牌，牌间覆盖属于有意排法。'],['本人筹码','figma','相对头像，短屏整体上移留出底栏。'],['其他玩家昵称','long','保留省略与字号缩放。'],['其他玩家筹码','long','复用ChipFormatter的大金额与BB规则。'],['玩家状态文字','status','等待/留座/托管在头像内部显示，各原因另列场景。'],['操作类型文字','actions','气泡避开昵称；全下使用原动画。'],['下注金额/图标','actions','本人和他人下注均以各自头像定位。'],['本人当前牌型','figma','环形移至手牌下方，跟随牌组。'],['赢家牌型/金额','settlement','赢家信息与亮牌分开，十种牌型另列场景。'],['主操作按钮位置/大小','actions','跟随本人头像，保留按钮缩放。'],['快捷下注位置/大小','actions','沿操作栏相对排列，可切3/5个。'],['拉杆/确认按钮','raise','新布局确认与加注同位，拉杆随头像上移。'],['行动/留座倒计时','acting-self','复用头像光圈与截止时间。'],['保险气泡/胜率','insurance-buying','分别模拟保险倒计时与全下胜率。']];
 html+='<details open><summary>逐元素验收表</summary><table><tr><th>元素 / 修改与判定范围</th><th>Figma 布局基准</th><th>当前实现</th></tr>';
 for(const[item,scene,note]of elements){rows.push({layout:name,label:item,covers:[item],steps:note,status:'已提供对照；专项几何见验证JSON'});html+='<tr><td><b>'+item+'</b><p>'+note+'</p><small>无独立状态稿时左图仅作布局基准。</small></td><td>'+(refs[id]?photo('reference/'+refs[id],name+'原图'):'原图待补')+'</td><td>'+photo('scenarios/'+id+'-'+scene+'.jpg',item)+'</td></tr>';}
 html+='</table></details>';
 html+='<details><summary>展开该布局全部场景逐条对照与模拟步骤</summary><table><tr><th>场景 / 元素 / 步骤 / 结果</th><th>Figma 布局基准</th><th>当前状态截图</th></tr>';
 for(const s of auditScenarios){const r=results.find(r=>r.layout===id&&r.id===s.id);const status=r?(r.errors.length?'脚本异常':'已采集；视觉见图'):'未采集';rows.push({layout:name,...s,status});html+=`<tr><td><b>${e(s.group)} · ${e(s.label)}</b><p>${e(s.covers.join('、'))}</p><p>${e(s.steps)}</p><small>${status}；${s.id==='figma'?'对应八人桌基准':'未提供该状态独立设计稿，左图仅核对布局关系'}。</small><p><a href="http://127.0.0.1:4179/tests/fixtures/layout-audit.html?layout=${id}&scene=${s.id}">打开离线场景</a></p></td><td>${refs[id]?photo('reference/'+refs[id],name+' 布局基准'):'原图待补'}</td><td>${r?photo(`scenarios/${id}-${s.id}.jpg`,s.label):'未采集'}</td></tr>`;}
 html+='</table></details><details><summary>五种视口：本人庄家、手牌与加注确认</summary><div>';for(const v of verify.filter(v=>v.layout===id&&v.width))html+=photo(`scenarios/${id}-${v.width}x${v.height}-anchors.jpg`,`${v.width}×${v.height}`);html+='</div></details>';
}
html+=`<h2>逐元素编辑器</h2><p>任一座位可独立编辑昵称、头像、操作文字、筹码、下注、性别值、胜率、等待状态、留座原因/截止时间、保险截止时间、蘑菇押金/参与、鱿鱼数量/参与/逃离、弃牌、托管、本轮已行动、手牌、选亮牌、高亮/上浮、赢家牌型/金额。另可切换庄家、行动座位与光圈，模拟下手站起、私局币和一手结束。这些是可组合的数据控制项，并不表示每一种组合均已验收。</p><h2 id="catalog">新增模拟清单（${auditScenarios.length} 个可选场景）</h2><p>每个场景可切四种布局、2–9 人、本人座位、状态作用座位、庄家座位、手牌数量、90%–110% 档位、语言、快捷下注数量与滑杆提交方式。完整手牌支持单步、播放、暂停、重置、重连、切桌、离桌和重进。</p><p><a href="offline-scenarios.json">完整场景 JSON（元素与步骤）</a> · <a href="acceptance.csv">全部逐布局记录 CSV</a></p><table><tr><th>组别</th><th>场景</th><th>新增元素</th><th>操作步骤</th></tr>${auditScenarios.map(s=>`<tr><td>${e(s.group)}</td><td>${e(s.label)}</td><td>${e(s.covers.join('、'))}</td><td>${e(s.steps)}</td></tr>`).join('')}</table><h2>模拟范围和仍需验收项</h2><p>工作台调用现有 GameClient / TableView 和业务窗口，本地 Host 提供确定性数据；不是截图摆放，也不连接游戏后端。音视频仅本地占位，不访问硬件或 RTC。外壳客服、安全卫士、支付订单、真实赛事服务端调度等未模拟为真实业务成功；因此不能声称所有线上流程已通过。动态动画时序、多语言长文案、全部设置组合及每一弹窗子流程仍需要专项交互验收；本报告保留其场景入口，不把一次截图当作覆盖。</p><p>运行：npm run dev -- --port 4179 --strictPort；打开 tests/fixtures/layout-audit.html。先运行 capture-audit-scenarios.mjs 与 verify-avatar-audit.mjs，再运行 build-figma-audit-report.mjs。截图依赖已安装 Playwright，MX_PLAYWRIGHT_MODULE 可指定路径。</p></main></html>`;
